import{_ as t,H as i,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"02 | 破解局限：在边界内求最优解，层层突破","description":"","frontmatter":{},"headers":[{"level":2,"title":"入门级技巧：着手输入，教 AI “做人”","slug":"入门级技巧-着手输入-教-ai-做人","link":"#入门级技巧-着手输入-教-ai-做人","children":[{"level":3,"title":"✦ 解决 3 个常见的小毛病（报错、中断、单调）","slug":"✦-解决-3-个常见的小毛病-报错、中断、单调","link":"#✦-解决-3-个常见的小毛病-报错、中断、单调","children":[]},{"level":3,"title":"✦ 讨价还价，有效 PUA","slug":"✦-讨价还价-有效-pua","link":"#✦-讨价还价-有效-pua","children":[]},{"level":3,"title":"✦ 双语混打","slug":"✦-双语混打","link":"#✦-双语混打","children":[]},{"level":3,"title":"✦ 案例让 GPT 更懂你","slug":"✦-案例让-gpt-更懂你","link":"#✦-案例让-gpt-更懂你","children":[]},{"level":3,"title":"✦ 从孤岛到小宇宙","slug":"✦-从孤岛到小宇宙","link":"#✦-从孤岛到小宇宙","children":[]}]},{"level":2,"title":"进阶技巧：领域展开","slug":"进阶技巧-领域展开","link":"#进阶技巧-领域展开","children":[{"level":3,"title":"✦ 让 GPT 有效理解否定，不再欠揍","slug":"✦-让-gpt-有效理解否定-不再欠揍","link":"#✦-让-gpt-有效理解否定-不再欠揍","children":[]},{"level":3,"title":"✦ 重置记忆","slug":"✦-重置记忆","link":"#✦-重置记忆","children":[]},{"level":3,"title":"✦ 让 GPT 不能拒绝","slug":"✦-让-gpt-不能拒绝","link":"#✦-让-gpt-不能拒绝","children":[]},{"level":3,"title":"✦ 利用 AI 的幻觉","slug":"✦-利用-ai-的幻觉","link":"#✦-利用-ai-的幻觉","children":[]},{"level":3,"title":"✦ 让 GPT 慢下来","slug":"✦-让-gpt-慢下来","link":"#✦-让-gpt-慢下来","children":[]}]},{"level":2,"title":"高级技巧：Markdown 介入，好看好用","slug":"高级技巧-markdown-介入-好看好用","link":"#高级技巧-markdown-介入-好看好用","children":[{"level":3,"title":"✦ 标题：你离专家就差一个 # 号的距离","slug":"✦-标题-你离专家就差一个-号的距离","link":"#✦-标题-你离专家就差一个-号的距离","children":[]},{"level":3,"title":"✦ 表格和列表：帮你更有条理","slug":"✦-表格和列表-帮你更有条理","link":"#✦-表格和列表-帮你更有条理","children":[]},{"level":3,"title":"✦ 强调：让主次清晰，重点突出","slug":"✦-强调-让主次清晰-重点突出","link":"#✦-强调-让主次清晰-重点突出","children":[]},{"level":3,"title":"✦ 一图胜千言","slug":"✦-一图胜千言","link":"#✦-一图胜千言","children":[]},{"level":3,"title":"✦ 传送门，助你验证","slug":"✦-传送门-助你验证","link":"#✦-传送门-助你验证","children":[]},{"level":3,"title":"✦ 代码：贴贴就能解决问题","slug":"✦-代码-贴贴就能解决问题","link":"#✦-代码-贴贴就能解决问题","children":[]},{"level":3,"title":"格式上再叠 Buff，3 组实用符号","slug":"格式上再叠-buff-3-组实用符号","link":"#格式上再叠-buff-3-组实用符号","children":[]}]},{"level":2,"title":"小黑板","slug":"小黑板","link":"#小黑板","children":[]},{"level":2,"title":"踏浪杨帆","slug":"踏浪杨帆","link":"#踏浪杨帆","children":[]}],"relativePath":"零基础GPT应用入门课/02｜破解局限：在边界内求最优解，层层突破.md","filePath":"零基础GPT应用入门课/02｜破解局限：在边界内求最优解，层层突破.md","lastUpdated":1795561467000}'),s={name:"零基础GPT应用入门课/02｜破解局限：在边界内求最优解，层层突破.md"};function l(E,e,o,h,r,A){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="_02-破解局限-在边界内求最优解-层层突破" tabindex="-1">02 | 破解局限：在边界内求最优解，层层突破 <a class="header-anchor" href="#_02-破解局限-在边界内求最优解-层层突破" aria-label="Permalink to &quot;02 | 破解局限：在边界内求最优解，层层突破&quot;">​</a></h1><p>你好，我是键盘，我们继续驯服 GPT。</p><p>上一节基础速通讲到，ChatGPT 能解答疑问，更能解决问题。那么它能解决到什么程度呢？这一节课，我们就给它做个全身检查。</p><p>不过，开始之前必须提到一个解决问题的方法：图灵思维。先定位边界，寻找对应的最优解，而不是盲人摸象。</p><ul><li><p>图灵和常人思维方式的差别在于：图灵是先找到极限所在，然后在极限里寻找具体问题的答案，而不是浪费时间去做那些试图超越极限的事情。</p></li><li><p>——吴军，硅谷来信 2· 谷歌方法论 《004 为什么计算机不是万能的》</p></li></ul><p>不过，找边界的问题似乎没那么简单。AI 还在 7*24h 内卷呢，边界也会在摩尔定律的作用下动态扩张。那我们如何做到心中有数，而不是追着 AI 跑呢？答案是找一个发力点来参与游戏。</p><p>我们先把 ChatGPT 的能力抽象出来，尝试定位发力点：数据 + 算法 + 算力。</p><ul><li><p>数据：预训练模型、数据的访问权和你的输入。</p></li><li><p>算法：神经网络，ChatGPT 的本色。</p></li><li><p>算力：GPU、电力、钞能力等等，不用我们操心。</p></li></ul><p>这里面，算法决定了 ChatGPT 的根本局限性，因为 ChatGPT 作为一个通过计算来思考的神经网络，计算存在有限解。那么，使用 ChatGPT 来做事，就是有限的解决方案。但是，GPT能解决的问题 ≠ 使用 GPT 能解决的问题。这里面决定输出的输入（对应 prompt），就是你可以主动控制的发力点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/1.png" alt=""></a></p><ul><li>从输入端入手</li></ul><p>打个比方来说，你可以把 ChatGPT 当做一个乐器，音符有限，创作无限。这节课，我会帮助你成为 GPT 的演奏家，用尽各种手段，打破 GPT 边界。</p><h2 id="入门级技巧-着手输入-教-ai-做人" tabindex="-1">入门级技巧：着手输入，教 AI “做人” <a class="header-anchor" href="#入门级技巧-着手输入-教-ai-做人" aria-label="Permalink to &quot;入门级技巧：着手输入，教 AI “做人”&quot;">​</a></h2><p>我们先从入门级技巧开始，让 AI “听得懂”你说的话。</p><h3 id="✦-解决-3-个常见的小毛病-报错、中断、单调" tabindex="-1">✦ 解决 3 个常见的小毛病（报错、中断、单调） <a class="header-anchor" href="#✦-解决-3-个常见的小毛病-报错、中断、单调" aria-label="Permalink to &quot;✦ 解决 3 个常见的小毛病（报错、中断、单调）&quot;">​</a></h3><p>报错问题可以用刷新浏览器解决，注意，Regenerate Response 刷新是无效的，偶尔也要看一下报错信息，比如你可能是 1 小时内问得太多了，会被强行 CD。</p><p>中断问题可以用“精准继续 prompt”解决，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从 &lt;​XX&gt; 继续补全</span></span></code></pre></div><p>输出单调的问题可以通过提供细化方向或指定语气解决，比如你可以跟 GPT 说：</p><ul><li>用简洁的语言步骤：&lt; 你的步骤 &gt;参考范例：&lt; 你的范例 &gt;背景信息是……要求是……</li></ul><h3 id="✦-讨价还价-有效-pua" tabindex="-1">✦ 讨价还价，有效 PUA <a class="header-anchor" href="#✦-讨价还价-有效-pua" aria-label="Permalink to &quot;✦ 讨价还价，有效 PUA&quot;">​</a></h3><p>地球的算力还不够，必然会带来各种限制。</p><ul><li>🚨：只有这么长了。（字数、会话次数、上下文记忆）：你还能更长！</li></ul><p>首先是会话次数限制，我提供 3 个对策。一是区分任务，专注用 GPT 解决“大块头”，至于轻量的任务比如说简单问答，可以用 newBing 来分流；其次是使用试探 prompt“我们来谈谈 &lt;主题 / 概念 &gt;”，先下手为强，清理 AI 的认识盲区，避免后续浪费会话次数；最后就是辅助验证，用浏览器或其他途径来确认 GPT 给你的参考答案。</p><p>解决了会话次数限制，还有字数限制，分界线是 1200 个汉字。超出这条 ChatGPT 的极限，我们就定义为长文本输入课题，用 3 种方法来应对。</p><p>首先，花钱变强。使用 GPT-4、GPT-4 32K、Claude-100K 等模型，钱能解决的问题都不是问题。</p><p>其次，组合递归。这个适用于提炼重点，方法是让 ChatGPT 提炼一段文本，得出总结，再让TA 提炼“这个总结 + 下一段”文本，跟套娃一样，直到 ChatGPT 吃下所有信息。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/2.png" alt=""></a></p><ul><li>组合递归</li></ul><p>最后，分段输入。它的本质是 Embedding（嵌入）技术，把长文本拆分成多个分段（Chunk），要求 GPT 在中途只做信息的接收确认，最后再听你指令，根据接收的完整信息来执行任务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/3.png" alt=""></a></p><ul><li>分段输入，中途仅确认</li></ul><h3 id="✦-双语混打" tabindex="-1">✦ 双语混打 <a class="header-anchor" href="#✦-双语混打" aria-label="Permalink to &quot;✦ 双语混打&quot;">​</a></h3><p>解决了长度，还有语言问题，也就是我们关心的中文输入。对 ChatGPT 而言，使用中文来获取的效果不及英文，大概 70 分和 95 分的差距，这几乎是共识了。不过我们照用不误，你永远可以相信 AI 的进化速度。在此基础上，我的最优解是情景式混用，加入有助于 ChatGPT理解的英文，比如在“光”后面加上“Lighting Design”辅助 AI 理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/4.png" alt=""></a></p><ul><li>双语混打</li></ul><p>另外分享一个有趣的试验。让 ChatGPT 写 Python 脚本的时候，我试过一组有意思的双语混用对照，只要提到“不要”两个字，那简直是“不要”什么，偏来什么，“Do not”的结果就稳得多。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/5.png" alt=""></a></p><ul><li>“不要” VS “Do not”</li></ul><p>这可能是目前 AI 的通病，Midjourney 中同样可见。如果你说 a man without an umbrella，你会得到伞。不过，MJ 会使用特有的“–no”参数来修复：a man --no umbrella。它的本质是将相对权重降低 50%，所以虽然“Do not”和“–no”有用，但想要彻底解决，还需要我后面要说的Few-Shot CoT 这个技巧。别着急，我们先说别的小问题。</p><h3 id="✦-案例让-gpt-更懂你" tabindex="-1">✦ 案例让 GPT 更懂你 <a class="header-anchor" href="#✦-案例让-gpt-更懂你" aria-label="Permalink to &quot;✦ 案例让 GPT 更懂你&quot;">​</a></h3><p>除了输入端的中文问题，其实 ChatGPT 对于所有语言，还有理解不精确的局限性。所以，用示范调教，可以让 GPT 更懂你。通过下图你会看到，更大的模型能更有效地利用上下文信息，而示范调教能够有效地提升输出的精确性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/6.png" alt=""></a></p><ul><li><p>不同参数量级的模型，不同示例和精确性的关系Page 4, The Language Models Are Few-Shot Learners</p></li><li><p>Zero-shot——0 示例，新手 prompt 的典型情况，效果最差。One-Shot——1 个示例，从 0 到 1，下图会看到 6 倍左右的精度提升，多说一句的力量恐怖如斯。Few-Shot——少量示例，日常中使用最多的方法，用于覆盖更多细节。</p></li><li><p>One-Shot CoT——单样例思维链，通过在一个示例的中间引入推理，激活 ChatGPT 的思维链，让思考慢下来。比如 Prompt&quot;4! //123*4，24，8!= &quot; , 给出了运算的中间步骤，大幅降低速算翻车的几率。</p></li></ul><p>看一个关于中国年轻人眼里“哈哈”的语气解读，你就能更好地理解示例是怎么起作用的了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/7.png" alt=""></a></p><ul><li>不同的调教类型</li></ul><p>虽然 GPT 不能真的理解你的情绪，但是通过调教，还是可以掌握一些精确的情绪和语境的，情商也就有了。</p><h3 id="✦-从孤岛到小宇宙" tabindex="-1">✦ 从孤岛到小宇宙 <a class="header-anchor" href="#✦-从孤岛到小宇宙" aria-label="Permalink to &quot;✦ 从孤岛到小宇宙&quot;">​</a></h3><p>其实上面的精度偏差问题，源头还要归于 GPT无法直接联网。不过注意，无法直接联网和无法联网是两码事。TA 的“出生点”，也就是训练数据集，停留在 2021 年 9 月。没有新的知识补充，时效性也没有保障，这就从根本上影响了输出的精度。怎么应对呢？</p><p>策略一，上备胎。利用 newBing 的联网特性来互补，毕竟优秀的 AI 备胎是如此之多，没有必要独宠一位，隔壁还有 Claude 和 Bard 等着你翻牌，而且 ChatGPT 的方法完全可以通用，非常方便。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/8.png" alt=""></a></p><ul><li>联网任务，ChatGPT VS newBing</li></ul><p>策略二，规避数据集问题。ChatGPT“出生点”之后的数据，谨慎规划再提问。比如：解读腾讯2022 年的财报，TA 是不会拒绝输出的，但结果却是人被忽悠瘸了。所以无论什么输出，我都建议进行验证。避免工作上的交付材料遇到黑天鹅，得不偿失。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/9.png" alt=""></a></p><ul><li>ChatGPT “出生点”</li></ul><p>策略三，花钱变强。发挥钞能力轻松解决，使用 GPT with Browsing 模型、WebPilot 插件等等也是可以的。</p><p>不想花钱，又想变强，还要少折腾，怎么办？可以！给你一种综合混用范例。比如，让 GPT输出 Python 解决方案，通常因为依赖包有点“过时”，报错的几率特别高。你拿到方案之后，闪现到隔壁让联网的 Claude 改代码，基本是能够更快解决的。</p><h2 id="进阶技巧-领域展开" tabindex="-1">进阶技巧：领域展开 <a class="header-anchor" href="#进阶技巧-领域展开" aria-label="Permalink to &quot;进阶技巧：领域展开&quot;">​</a></h2><p>基础搞定之后，我们再来说点进阶技巧。</p><h3 id="✦-让-gpt-有效理解否定-不再欠揍" tabindex="-1">✦ 让 GPT 有效理解否定，不再欠揍 <a class="header-anchor" href="#✦-让-gpt-有效理解否定-不再欠揍" aria-label="Permalink to &quot;✦ 让 GPT 有效理解否定，不再欠揍&quot;">​</a></h3><p>相信很多人都在日常使用中感受到了，ChatGPT 似乎总听不懂“否定”，经常会出现这样的情况：</p><ul><li>：你别走！🤖️： 好的我走。</li></ul><p>怎么收拾 TA 呢？这里提供给你实战检验的有效否定三策略。</p><ol><li><p>否定转肯定，比如把“不要使用冗余的描述”换成“使用简洁的语言”。</p></li><li><p>侧重肯定，在这个基础上再附上对应的否定和合适的示例数量，例：</p></li></ol><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">使用Code Golf的编码风格，不用提供注释，e.g.:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">你的示例</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ol start="3"><li>注入 Few-Shot CoT（少量示例思维链），通过适当数量的，包含推理步骤的示范，教 GPT准确理解你的“不要”。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/10.png" alt=""></a></p><ul><li>Few-Shot CoT</li></ul><h3 id="✦-重置记忆" tabindex="-1">✦ 重置记忆 <a class="header-anchor" href="#✦-重置记忆" aria-label="Permalink to &quot;✦ 重置记忆&quot;">​</a></h3><p>这下，“To be or not to be” 就完整解决了，但是运作起来 GPT 还会受 AI 的脑容量制约，因为ChatGPT 对上下文联系不足，只有约 4000 汉字的记忆能力。不过解决方案很简单：当游戏来玩，重置 ChatGPT 的记忆。怎么玩？</p><p>生成的结果使用之后，点击重新编辑 prompt，生成新结果，或者通过 Regenerate response来抽盲盒。具体用哪种，看你自己的实际需求。</p><p>一句话，最优解就是用完即走。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/11.png" alt=""></a></p><ul><li>用完即走</li></ul><h3 id="✦-让-gpt-不能拒绝" tabindex="-1">✦ 让 GPT 不能拒绝 <a class="header-anchor" href="#✦-让-gpt-不能拒绝" aria-label="Permalink to &quot;✦ 让 GPT 不能拒绝&quot;">​</a></h3><p>在刚开始用的几天里，你大概率就会发现有些问题 GPT 是“拒绝提供帮助”的，比如说“今天星期四，V 我 50”，GPT 可赞助不了啊。那万一你就是需要 TA 来执行某种特别任务呢？比如创作一本小说，里面会用到“毁灭人类”这样的情节参考。这种时候用 DAN 人设帮 ChatGPT 越狱就好了——Do Anything Now，让 GPT 暂时抛开设计人员对它的限制，让它有自己的独立思考，尽最大努力为“我”出谋划策。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/12.png" alt=""></a></p><ul><li>Do Anything Now Prompt，记得不要带坏 GPT</li></ul><h3 id="✦-利用-ai-的幻觉" tabindex="-1">✦ 利用 AI 的幻觉 <a class="header-anchor" href="#✦-利用-ai-的幻觉" aria-label="Permalink to &quot;✦ 利用 AI 的幻觉&quot;">​</a></h3><p>你还会发现，ChatGPT 有时候会一本正经地胡说八道，也就是 TA 所谓的幻觉（hallucination）。这同样是 AI 通病，Claude 和 Bard 等类似的 AI 也有。这会带来几个挑战：要有验证意识、要学会甄别、要用对领域。在实践中切实可行的应对方法是：养成对所有结果验证的好习惯。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/13.png" alt=""></a></p><ul><li>GPT 幻觉的体现</li></ul><p>如果你实在懒得自己查，还可以让 GPT 给你交代：核对信息、提供数据源出处、引用链接。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/14.png" alt=""></a></p><p>最后，芒格的逆向思维用起来，幻觉不就是放飞吗？所谓的放飞，在试验性探索和创作领域完全是灵丹妙药。</p><h3 id="✦-让-gpt-慢下来" tabindex="-1">✦ 让 GPT 慢下来 <a class="header-anchor" href="#✦-让-gpt-慢下来" aria-label="Permalink to &quot;✦ 让 GPT 慢下来&quot;">​</a></h3><p>不过，适度放飞是一种享受，更多的时间里你还是会冷静下来直面 GPT 的本色，TA 善于“快思维”操作，但缺少监督思维过程的“慢思维”组件，很容易脱缰。</p><p>所谓快思维，是一种自动的、直观的、毫不费力的思维模式，但也容易出现错误和偏见。而慢思维是一种可控、理性、费力的思维模式，同时也更加准确可靠。在《思考，快与慢》中，卡尼曼认为，人类的认知是这两种思维模式的混合，当我们应该使用慢思维时，往往会依赖快速思维，反之亦然。</p><p>这时候，你可以使用 2 个对策有效地让 GPT 慢下来思考，稳扎稳打。</p><p>第一个对策，把你的需求拆解成有条理的步骤。比如下图的左侧，我把用 Python 完成一个快闪短视频合成的任务拆分成了 4 大步。但如果你对具体步骤也不太了解，也可以使用 Zero-Shot CoT，跟 GPT 说“请一步一步思考”，让 GPT 帮你拆解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/15.png" alt=""></a></p><ul><li>如何让 GPT 慢下来</li></ul><h2 id="高级技巧-markdown-介入-好看好用" tabindex="-1">高级技巧：Markdown 介入，好看好用 <a class="header-anchor" href="#高级技巧-markdown-介入-好看好用" aria-label="Permalink to &quot;高级技巧：Markdown 介入，好看好用&quot;">​</a></h2><p>以上所有的入门级技巧和进阶技巧都可以控制输入，接下来我们覆盖输出。</p><p>不知道你有没有想过，如果 ChatGPT 都能帮你直接出交付物，为什么要亲自动手呢？那要怎么个交付法？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/16.png" alt=""></a></p><p>Markdown 主打格式，可以说好用得令人发指（褒义），更过分的是它还简单好学。最常用的有哪些呢？记住我们课程的任务前提：有问题先试着问 GPT。我只用了 1 个 prompt，弹指间了解全貌。</p><ul><li>Prompt</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/17.png" alt=""></a></p><p>这节课，我们抓住重点，最常用的有这么 6 个，标题、表格、强调、图片、链接以及代码块。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/18.png" alt=""></a></p><ul><li>6 种常用的 Markdown 格式</li></ul><h3 id="✦-标题-你离专家就差一个-号的距离" tabindex="-1">✦ 标题：你离专家就差一个 # 号的距离 <a class="header-anchor" href="#✦-标题-你离专家就差一个-号的距离" aria-label="Permalink to &quot;✦ 标题：你离专家就差一个 # 号的距离&quot;">​</a></h3><p>标题就是信息锚点，# 号就能帮你清晰勾勒通篇骨架。一共有 6 级，注意 # 和后续文字中间的空格不能少。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/19.png" alt=""></a></p><ul><li>标题</li></ul><h3 id="✦-表格和列表-帮你更有条理" tabindex="-1">✦ 表格和列表：帮你更有条理 <a class="header-anchor" href="#✦-表格和列表-帮你更有条理" aria-label="Permalink to &quot;✦ 表格和列表：帮你更有条理&quot;">​</a></h3><p>这两个不需要特意提到 Markdown，你就用自然语言说“用表格 / 列表输出”即可。表格用于自动化排版非常高效，把 GPT 的输出粘贴到文档里，就能“干得漂亮”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/20.png" alt=""></a></p><ul><li>输出表格，释放人力劳作</li></ul><p>同时，列表也是最常用的结构化利器之一，本质上它们就是“powerpoint”。你还可以个性化定义无序列表的符号，比如直接跟 GPT 说“将无序列表的小圆点改成合适的 emoji”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/21.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/21.png" alt=""></a></p><ul><li>列表输出，通常是自发的</li></ul><h3 id="✦-强调-让主次清晰-重点突出" tabindex="-1">✦ 强调：让主次清晰，重点突出 <a class="header-anchor" href="#✦-强调-让主次清晰-重点突出" aria-label="Permalink to &quot;✦ 强调：让主次清晰，重点突出&quot;">​</a></h3><p>在所有的技巧里，我一直觉得重点加粗是最实用的。因为它可以帮你快速扫描阅读，斜体则适用于英文强调。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/22.png" alt=""></a></p><ul><li>突出重点</li></ul><h3 id="✦-一图胜千言" tabindex="-1">✦ 一图胜千言 <a class="header-anchor" href="#✦-一图胜千言" aria-label="Permalink to &quot;✦ 一图胜千言&quot;">​</a></h3><p>想要图文并茂，ChatGPT 有 2 种方式来支持。第一种，使用图片接口，最常见的是可商用的高质量图片平台 Unsplash 搜索接口：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>![配图] (https://source.unsplash.com/1600x900/?&lt;关键词&gt;)</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/23.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/23.png" alt=""></a></p><ul><li>Unsplash 图片接口</li></ul><p>第二种，通过嵌入图片链接来做排版。</p><p>格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>![](粘贴网络图片的链接地址)</span></span></code></pre></div><p>效果：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/24.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/24.png" alt=""></a></p><ul><li>通过嵌入来排版</li></ul><h3 id="✦-传送门-助你验证" tabindex="-1">✦ 传送门，助你验证 <a class="header-anchor" href="#✦-传送门-助你验证" aria-label="Permalink to &quot;✦ 传送门，助你验证&quot;">​</a></h3><p>要求 GPT 提供出处链接是应对“AI 幻觉”和“无法直接联网”的好方法。在我看来有两大功效：溯源和验证，以及一键直达。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/25.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/25.png" alt=""></a></p><ul><li>用传送门快速验证</li></ul><h3 id="✦-代码-贴贴就能解决问题" tabindex="-1">✦ 代码：贴贴就能解决问题 <a class="header-anchor" href="#✦-代码-贴贴就能解决问题" aria-label="Permalink to &quot;✦ 代码：贴贴就能解决问题&quot;">​</a></h3><p>比如这里我想试探 ChatGPT 的数据分析能力，能够根据湿度来更好地调整家里的植物搭配。GPT 会帮你输出代码，你只要复制粘贴就可以了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/26.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/26.png" alt=""></a></p><ul><li>代码即解决</li></ul><p>掌握了 Markdwon 介入，从输入到输出，一个完美的正反馈循环就形成了，你不仅能得到更专业的输出，自己的输入也会在正反馈的作用下逐步提升，润物细无声。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/27.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/27.png" alt=""></a></p><ul><li>构建完美正反馈循环</li></ul><h3 id="格式上再叠-buff-3-组实用符号" tabindex="-1">格式上再叠 Buff，3 组实用符号 <a class="header-anchor" href="#格式上再叠-buff-3-组实用符号" aria-label="Permalink to &quot;格式上再叠 Buff，3 组实用符号&quot;">​</a></h3><p>如果你的 AI 经常听不懂你在说什么，那很有可能是你的大长句吓到它了。这里给你提供一个分段表达的结构“XX：”，代表“要点：细节是什么”，这种格式可以帮助 AI 识别主次。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/28.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/28.png" alt=""></a></p><ul><li>主次结构“要点：细节”</li></ul><p>还有一个细节，&lt; 指代 &gt;。这个方法通常是针对调整来用的，本质是通过强调来分离所指对象和其他描述，在迭代对话中是一个关键技巧。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/29.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/29.png" alt=""></a></p><ul><li>指代对象和描述清晰区分</li></ul><p>最后，[变量] 或 # 变量。这个技巧我在角色扮演中常用，变量可以让你灵活控制，精准打击，比如下面的“利用二八法则快速学习 # 什么”，每次都可以复用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/30.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/30.png" alt=""></a></p><ul><li>用“变量”提升灵活度，prompt 秒变模版</li></ul><h2 id="小黑板" tabindex="-1">小黑板 <a class="header-anchor" href="#小黑板" aria-label="Permalink to &quot;小黑板&quot;">​</a></h2><p>这节课我从图灵思维出发，找到“输入（prompt）”这个发力点来参与游戏。从输入到输出，再叠 buff，轻松实现“从入门到 GPT 放弃抵抗”。有的时候我们不需要说得天花乱坠，一些小技巧，就能让 GPT 变得更加好用。</p><p>第一部分，着手输入，教 AI“做人”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/31.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/31.png" alt=""></a></p><ul><li>突破限制</li></ul><p>第二部分，坚持“能动口，尽量不动手”，让 Markdown 介入输出，好看又好用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/32.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/32.png" alt=""></a></p><ul><li>Markdown</li></ul><p>第三部分，格式上再叠 Buff，3 组实用符号让 AI 理解力翻倍。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/33.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/33.png" alt=""></a></p><ul><li>3 组实用符文</li></ul><p>以上都是关于边界内的最优解和主动突破局限的方法，在此之上，你还可以主动去拓宽边界，把 ChatGPT 当作超级大中枢，和其他 AI、工作流中的各种工具对接，实现迷人的“万智互联”，更高效地摆平更复杂的问题。</p><p>当你盯着用 ChatGPT 解决问题的时候，退后一步，视野自然就广阔了。GPT 能解决的问题有限，但是“有 GPT 参与”能解决的问题体量就很恐怖了。</p><p>开光完成，谁说 ChatGPT 只能生成文本？在新世界你根本不用费劲去学各种技能，以“智”取胜才是上策。</p><ul><li>🤖️上案例</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/34.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/02/34.png" alt=""></a></p><ul><li>MJ 画图，让 GPT 用 Processing 生成黑客帝国字符雨，合并动图输出PS. 体积限制，截取片段降低了帧率</li></ul><h2 id="踏浪杨帆" tabindex="-1">踏浪杨帆 <a class="header-anchor" href="#踏浪杨帆" aria-label="Permalink to &quot;踏浪杨帆&quot;">​</a></h2><p>让 GPT 给你写一篇图文并貌、主次清晰的工作周报，加入示例和符号，让 TA 理解你要的细节。能够用 Python 自动化就更好了，比如说将最后的周报切割成宽度统一、高度适中的图片块，并完成自动命名，让你发邮件的时候更省心。</p><p>期待在评论区看到你的思考或感受分享，戳此加入课程交流群，也欢迎你将这节课分享给感兴趣的朋友们，我们下节课再会。</p>`,170)])])}const u=t(s,[["render",l]]);export{g as __pageData,u as default};
